<?php
namespace Tests\Unit;
use App\Modules\Tasks\Models\{ChecklistExecution,ChecklistItem,TaskExecution}; use App\Modules\Tasks\Support\TaskExecutionStatus; use Carbon\Carbon; use PHPUnit\Framework\TestCase;
class TaskExecutionStatusTest extends TestCase { private function execution(?string $completedAt, string $due='12:00'): TaskExecution { $item=new ChecklistItem(['due_time'=>$due]); $checklist=new ChecklistExecution(['execution_date'=>'2026-08-26']); $execution=new TaskExecution(['completed_at'=>$completedAt]); $execution->setRelation('checklistItem',$item); $execution->setRelation('checklistExecution',$checklist); return $execution; } public function test_statuses_are_calculated_not_stored(): void { $this->assertSame(TaskExecutionStatus::InProgress,$this->execution(null)->status(Carbon::parse('2026-08-26 09:00'))); $this->assertSame(TaskExecutionStatus::DueSoon,$this->execution(null)->status(Carbon::parse('2026-08-26 11:30'))); $this->assertSame(TaskExecutionStatus::Overdue,$this->execution(null)->status(Carbon::parse('2026-08-26 12:01'))); $this->assertSame(TaskExecutionStatus::CompletedOnTime,$this->execution('2026-08-26 11:00')->status(Carbon::now())); $this->assertSame(TaskExecutionStatus::CompletedLate,$this->execution('2026-08-26 13:00')->status(Carbon::now())); } }
